\n}\n\n.地图-区列表 {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));\n  gap: 12px;\n  overflow-y: auto;\n  scrollbar-width: thin;\n  scrollbar-color: rgba(35, 32, 27, 0.18) transparent;\n}\n\n.地图-区 {\n  padding: 10px 12px 12px;\n  border: 1px solid var(--墨线);\n  border-radius: 2px;\n  background: rgba(255, 255, 255, 0.5);\n\n  &.地图-区在此 {\n    border-color: rgba(156, 43, 35, 0.5);\n    background: rgba(156, 43, 35, 0.05);\n  }\n}\n\n.地图-区名 {\n  display: flex;\n  align-items: baseline;\n  justify-content: space-between;\n  gap: 8px;\n  margin: 0 0 8px;\n  font-family: var(--字体题签);\n  font-size: 14px;\n  font-weight: 400;\n  letter-spacing: 0.18em;\n  color: var(--墨);\n\n  em {\n    font-style: normal;\n    font-size: 11px;\n    letter-spacing: 0.06em;\n    color: var(--墨微);\n  }\n}\n\n.地图-地点列表 {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 6px;\n}\n\n.地图-地点 {\n  padding: 5px 11px;\n  font-family: inherit;\n  font-size: 12.5px;\n  letter-spacing: 0.06em;\n  color: var(--墨);\n  background: rgba(255, 255, 255, 0.72);\n  border: 1px solid var(--墨线);\n  border-radius: 2px;\n  cursor: pointer;\n  transition:\n    border-color 0.16s ease,\n    background 0.16s ease,\n    color 0.16s ease;\n\n  &:hover:not(:disabled) {\n    color: var(--朱砂);\n    background: rgba(255, 255, 255, 0.96);\n    border-color: rgba(156, 43, 35, 0.5);\n  }\n\n  &:disabled {\n    opacity: 0.4;\n    cursor: not-allowed;\n  }\n\n  &.地图-地点在此 {\n    color: #fdfbf6;\n    background: var(--朱砂);\n    border-color: var(--朱砂);\n\n    &:hover:not(:disabled) {\n      color: #fdfbf6;\n      background: #ac342a;\n    }\n  }\n}\n","/**\n * 全屏界面共用的水墨装饰.\n *\n * 颜色和字体不放在这里, 而是定义在 App.vue 根节点上的 CSS 变量里 —— 自定义属性会随 DOM\n * 继承下去, 子组件直接 `var()` 就能用; 这里只放需要反复复用的绘制规则.\n */\n\n/**\n * 版框: 往里收一圈细线, 四角再各压一道短线.\n *\n * 用的是 `::before`, 所以组件自己的 `::after` 仍然空着可用.\n *\n * @param 边距 内框离元素边缘的距离\n * @param 角长 四角短线的长度\n * @param 线色 内框线颜色\n * @param 角色 四角短线颜色\n */\n@mixin 版框($边距: 6px, $角长: 14px, $线色: var(--墨线淡), $角色: var(--朱砂线)) {\n  &::before {\n    content: '';\n    position: absolute;\n    inset: $边距;\n    border: 1px solid $线色;\n    pointer-events: none;\n\n    /* 四角各一横一竖, 拼成角线 */\n    background-image:\n      linear-gradient($角色, $角色), linear-gradient($角色, $角色), linear-gradient($角色, $角色),\n      linear-gradient($角色, $角色), linear-gradient($角色, $角色), linear-gradient($角色, $角色),\n      linear-gradient($角色, $角色), linear-gradient($角色, $角色);\n    background-size:\n      $角长 1px,\n      1px $角长,\n      $角长 1px,\n      1px $角长,\n      $角长 1px,\n      1px $角长,\n      $角长 1px,\n      1px $角长;\n    background-position:\n      left top,\n      left top,\n      right top,\n      right top,\n      left bottom,\n      left bottom,\n      right bottom,\n      right bottom;\n    background-repeat: no-repeat;\n  }\n}\n\n/**\n * 两端淡出的双线, 用来当书眉线、版心线.\n *\n * 竖着排一深一浅两道细线, 再用遮罩把两端化开, 比生硬的 border-bottom 有笔意.\n */\n@mixin 双线($深: rgba(35, 32, 27, 0.38), $浅: rgba(35, 32, 27, 0.14)) {\n  height: 3px;\n  background: linear-gradient(180deg, $深 0 1px, transparent 1px 2px, $浅 2px 3px);\n  -webkit-mask-image: linear-gradient(90deg, transparent, #000 12%, #000 88%, transparent);\n  mask-image: linear-gradient(90deg, transparent, #000 12%, #000 88%, transparent);\n}\n\n/** 纸上的柔和墨晕, 代替现代的硬投影 */\n@mixin 墨晕($模糊: 26px, $强度: 0.07) {\n  box-shadow: 0 ($模糊 * 0.38) $模糊 rgba(74, 58, 38, $强度);\n}\n"],"sourceRoot":""}]);
