CE,CAQF,2GACE,CAQF,2BAAA,CDpCJ,iCACE,aAAA,CACA,UAAA,CACA,WAAA,CACA,gBAAA,CAGF,iCACE,YAAA,CACA,UAAA,CACA,WAAA,CACA,qBAAA,CACA,kBAAA,CACA,sBAAA,CACA,OAAA,CACA,kIACE,CAKJ,iCACE,iBAAA,CACA,aAAA,CACA,oCAAA,CACA,iBAAA,CACA,mBAAA,CAGF,gCACE,uBAAA,CACA,aAAA,CACA,aAAA,CACA,wBAAA,CAGF,gCACE,uBAAA,CACA,eAAA,CACA,oBAAA,CACA,iBAAA,CACA,eAAA","sourcesContent":["\n@use '../水墨' as *;\n\n/* 立绘按挂轴的样式裱一下: 一圈细线, 四角压角线 */\n.portrait {\n  position: relative;\n  overflow: hidden;\n  background: linear-gradient(165deg, #f1ebdd 0%, #ddd2bd 100%);\n  /* 角线取短一点: 周遭栏的头像是 48×64 的小图, 角线太长会顶满整条边 */\n  @include 版框(3px, 7px, rgba(35, 32, 27, 0.13), rgba(138, 106, 68, 0.55));\n}\n\n.portrait-image {\n  display: block;\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n}\n\n.portrait-blank {\n  display: flex;\n  width: 100%;\n  height: 100%;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n  background:\n    radial-gradient(circle at 50% 34%, rgba(156, 43, 35, 0.09), transparent 64%),\n    linear-gradient(165deg, #f4eee1 0%, #ddd2bd 100%);\n}\n\n/* 空位用一枚虚圈示意 */\n.portrait-frame {\n  position: absolute;\n  inset: 13% 17%;\n  border: 1px dashed rgba(35, 32, 27, 0.22);\n  border-radius: 50%;\n  pointer-events: none;\n}\n\n.portrait-word {\n  font-family: var(--字体题签);\n  font-size: 3em;\n  line-height: 1;\n  color: rgba(156, 43, 35, 0.4);\n}\n\n.portrait-name {\n  font-family: var(--字体题签);\n  font-size: 0.78em;\n  letter-spacing: 0.26em;\n  text-indent: 0.26em;\n  color: var(--墨微);\n}\n","/**\n * 全屏界面共用的水墨装饰.\n *\n * 颜色和字体不放在这里, 而是定义在 App.vue 根节点上的 CSS 变量里 —— 自定义属性会随 DOM\n * 继承下去, 子组件直接 `var()` 就能用; 这里只放需要反复复用的绘制规则.\n */\n\n/**\n * 版框: 往里收一圈细线, 四角再各压一道短线.\n *\n * 用的是 `::before`, 所以组件自己的 `::after` 仍然空着可用.\n *\n * @param 边距 内框离元素边缘的距离\n * @param 角长 四角短线的长度\n * @param 线色 内框线颜色\n * @param 角色 四角短线颜色\n */\n@mixin 版框($边距: 6px, $角长: 14px, $线色: var(--墨线淡), $角色: var(--朱砂线)) {\n  &::before {\n    content: '';\n    position: absolute;\n    inset: $边距;\n    border: 1px solid $线色;\n    pointer-events: none;\n\n    /* 四角各一横一竖, 拼成角线 */\n    background-image:\n      linear-gradient($角色, $角色), linear-gradient($角色, $角色), linear-gradient($角色, $角色),\n      linear-gradient($角色, $角色), linear-gradient($角色, $角色), linear-gradient($角色, $角色),\n      linear-gradient($角色, $角色), linear-gradient($角色, $角色);\n    background-size:\n      $角长 1px,\n      1px $角长,\n      $角长 1px,\n      1px $角长,\n      $角长 1px,\n      1px $角长,\n      $角长 1px,\n      1px $角长;\n    background-position:\n      left top,\n      left top,\n      right top,\n      right top,\n      left bottom,\n      left bottom,\n      right bottom,\n      right bottom;\n    background-repeat: no-repeat;\n  }\n}\n\n/**\n * 两端淡出的双线, 用来当书眉线、版心线.\n *\n * 竖着排一深一浅两道细线, 再用遮罩把两端化开, 比生硬的 border-bottom 有笔意.\n */\n@mixin 双线($深: rgba(35, 32, 27, 0.38), $浅: rgba(35, 32, 27, 0.14)) {\n  height: 3px;\n  background: linear-gradient(180deg, $深 0 1px, transparent 1px 2px, $浅 2px 3px);\n  -webkit-mask-image: linear-gradient(90deg, transparent, #000 12%, #000 88%, transparent);\n  mask-image: linear-gradient(90deg, transparent, #000 12%, #000 88%, transparent);\n}\n\n/** 纸上的柔和墨晕, 代替现代的硬投影 */\n@mixin 墨晕($模糊: 26px, $强度: 0.07) {\n  box-shadow: 0 ($模糊 * 0.38) $模糊 rgba(74, 58, 38, $强度);\n}\n"],"sourceRoot":""}]);
