\n  font-size: 12px;\n}\n\n.hero-fade {\n  position: absolute;\n  inset: 0;\n  pointer-events: none;\n  background: linear-gradient(180deg, transparent 44%, rgba(28, 24, 20, 0.82) 100%);\n}\n\n.hero-badge {\n  position: absolute;\n  top: 8px;\n  right: 8px;\n  padding: 2px 8px;\n  font-family: var(--字体题签);\n  font-size: 11px;\n  letter-spacing: 0.1em;\n  color: #f6efe2;\n  background: rgba(156, 43, 35, 0.86);\n  border-radius: 2px;\n}\n\n.hero-name {\n  position: absolute;\n  right: 10px;\n  bottom: 8px;\n  left: 10px;\n  text-align: center;\n}\n\n.hero-name-main {\n  margin: 0;\n  font-family: var(--字体题签);\n  font-size: 19px;\n  letter-spacing: 0.16em;\n  text-indent: 0.16em;\n  color: #fbf7ee;\n  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.7);\n}\n\n.hero-name-sub {\n  margin: 2px 0 0;\n  font-size: 11px;\n  letter-spacing: 0.18em;\n  color: rgba(246, 239, 226, 0.82);\n}\n\n/* --- 身份 / 简介 --- */\n.hero-identity {\n  margin: 0 0 6px;\n  font-size: 12px;\n  letter-spacing: 0.12em;\n  text-align: center;\n  color: var(--朱砂);\n}\n\n.hero-intro {\n  margin: 0 0 8px;\n  font-size: 12px;\n  line-height: 1.85;\n  color: var(--墨淡);\n  text-indent: 2em;\n}\n\n.hero-empty {\n  margin: 0 0 8px;\n  font-size: 12px;\n  line-height: 1.8;\n  text-align: center;\n  color: var(--墨微);\n}\n\n/* --- 小标题: 两侧各一条淡出的细线, 中间是楷体题字 --- */\n.hero-title {\n  display: grid;\n  grid-template-columns: 1fr auto 1fr;\n  align-items: center;\n  gap: 10px;\n  margin: 15px 0 8px;\n  font-family: var(--字体题签);\n  font-size: 12px;\n  font-weight: 400;\n  letter-spacing: 0.3em;\n  text-indent: 0.3em;\n  text-align: center;\n  color: var(--墨淡);\n\n  &::before,\n  &::after {\n    content: '';\n    height: 1px;\n  }\n\n  &::before {\n    background: linear-gradient(90deg, transparent, rgba(35, 32, 27, 0.26));\n  }\n\n  &::after {\n    background: linear-gradient(90deg, rgba(35, 32, 27, 0.26), transparent);\n  }\n}\n\n/* --- 境界 --- */\n.hero-realm {\n  margin: 0;\n  font-family: var(--字体题签);\n  font-size: 15px;\n  letter-spacing: 0.2em;\n  text-indent: 0.2em;\n  text-align: center;\n  color: var(--墨);\n}\n\n.hero-realm-desc {\n  margin: 6px 0 0;\n  font-size: 12px;\n  line-height: 1.85;\n  color: var(--墨淡);\n  text-indent: 2em;\n}\n\n.hero-realm-power {\n  margin: 6px 0 0;\n  padding: 7px 9px;\n  font-size: 12px;\n  line-height: 1.8;\n  color: var(--墨淡);\n  background: rgba(156, 43, 35, 0.05);\n  border-left: 2px solid rgba(156, 43, 35, 0.45);\n  border-radius: 2px;\n}\n\n.hero-realm-power-tag {\n  margin-right: 6px;\n  font-family: var(--字体题签);\n  font-size: 11px;\n  letter-spacing: 0.1em;\n  color: var(--朱砂);\n  white-space: nowrap;\n}\n\n/* --- 修为 --- */\n.hero-cultivation {\n  display: grid;\n  grid-template-columns: auto 1fr auto;\n  align-items: center;\n  gap: 8px;\n  margin-top: 10px;\n  font-size: 12px;\n}\n\n.hero-cultivation-name {\n  font-family: var(--字体题签);\n  letter-spacing: 0.12em;\n  color: var(--墨淡);\n}\n\n.hero-bar {\n  height: 6px;\n  background: rgba(35, 32, 27, 0.08);\n  border: 1px solid var(--墨线);\n  border-radius: 4px;\n  overflow: hidden;\n}\n\n.hero-bar-fill {\n  display: block;\n  height: 100%;\n  background: linear-gradient(90deg, rgba(156, 43, 35, 0.6), var(--朱砂));\n  transition: width 0.6s ease;\n}\n\n.hero-cultivation-value {\n  color: var(--墨);\n  font-variant-numeric: tabular-nums;\n\n  i {\n    font-style: normal;\n    font-size: 0.9em;\n    color: var(--墨微);\n  }\n}\n\n.hero-rate {\n  margin: 6px 0 0;\n  font-size: 11px;\n  line-height: 1.7;\n  text-align: center;\n  color: var(--墨微);\n\n  i {\n    font-style: normal;\n  }\n}\n\n/* --- 脚本上一轮做了什么 --- */\n.hero-log {\n  margin: 8px 0 0;\n  padding: 6px 8px;\n  font-size: 10px;\n  line-height: 1.7;\n  color: var(--墨微);\n  background: rgba(35, 32, 27, 0.04);\n  border-left: 2px solid rgba(35, 32, 27, 0.22);\n  border-radius: 2px;\n}\n\n/* --- 双修对象及其加成 --- */\n.hero-dual {\n  margin: 6px 0 0;\n  padding: 0;\n  list-style: none;\n  font-size: 11px;\n\n  li {\n    display: flex;\n    align-items: baseline;\n    gap: 6px;\n    padding-left: 10px;\n    color: var(--墨淡);\n  }\n}\n\n.hero-dual-name {\n  flex: none;\n  color: var(--墨);\n}\n\n.hero-dual-stage {\n  flex: 1 1 auto;\n  overflow: hidden;\n  color: var(--朱砂);\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n/* --- 修行 --- */\n.hero-rows {\n  display: grid;\n  grid-template-columns: auto 1fr;\n  gap: 4px 10px;\n  margin: 0;\n  font-size: 12px;\n\n  dt {\n    font-family: var(--字体题签);\n    letter-spacing: 0.12em;\n    color: var(--墨淡);\n  }\n\n  dd {\n    display: flex;\n    align-items: baseline;\n    justify-content: space-between;\n    gap: 8px;\n    min-width: 0;\n    margin: 0;\n  }\n}\n\n.hero-rows-text {\n  overflow: hidden;\n  color: var(--墨);\n  text-overflow: ellipsis;\n  white-space: nowrap;\n}\n\n.hero-times {\n  flex: none;\n  font-style: normal;\n  font-variant-numeric: tabular-nums;\n  color: var(--朱砂);\n}\n\n/* --- 状态 --- */\n.hero-tags {\n  display: flex;\n  flex-wrap: wrap;\n  gap: 5px;\n}\n\n.hero-tag {\n  padding: 2px 8px;\n  font-size: 11px;\n  color: var(--墨);\n  background: rgba(156, 43, 35, 0.08);\n  border: 1px solid rgba(156, 43, 35, 0.34);\n  border-radius: 2px;\n  cursor: help;\n}\n\n/* --- 物品 --- */\n.hero-items {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n  font-size: 12px;\n\n  li {\n    position: relative;\n    padding-left: 12px;\n    color: var(--墨);\n\n    &::before {\n      content: '·';\n      position: absolute;\n      left: 3px;\n      color: var(--朱砂);\n    }\n  }\n\n  em {\n    font-style: normal;\n    color: var(--墨微);\n  }\n}\n"],"sourceRoot":""}]);
