/**
 * 修仙恋爱角色卡 —— MVU 变量结构 (zod 4)
 *
 * 它是这张卡的「唯一事实来源」: 世界书里的 `变量更新规则` 是它的自然语言版,
 * `initvar.yaml` 是它的初始值版, `../../全屏前端界面/schema.ts` 是它的显示层宽松版.
 * 三者字段名必须一致, 改动任何一处都要同步另外两处.
 *
 * ## 修行主体例
 *
 *   修炼倍率 = 灵根倍率 × 主修功法倍率 × 双修倍率
 *   修为增速 = 境界速率 × 修炼倍率              (单位: 修为/日)
 *   修为上限 = 境界上限
 *
 * 境界越高 **速率越高, 但上限涨得更快**, 所以突破要的时间依次变长,
 * 从炼气的一年一路涨到大乘的三百年 (见 `境界表` 与 `纯修年`).
 * 主修功法取倍率最高的一门; 双修是所有双修对象按好感度阶段给出的加成之和再加 1.
 *
 * ## 历法
 *
 * 一年 **365 日, 不设闰年** (见 `一年日数` 与 `每月天数`). 时间由脚本按天数推进,
 * `世界.历日` 是从大衍历元年正月初一起算的第几天, `世界.$当前时间` 由它格式化而来.
 *
 * ## 地图
 *
 * 地图是**固定的**: 六个大区域, 每个大区域下辖若干小区域 (见 `地图`).
 * 小区域之间走动不花时间; 跨大区域移动要按 `跨区日数` 跳过若干天, 由脚本自动补上.
 *
 * 修为的推进、境界的突破、历日的推进、跨区移动的耗时**全部由脚本完成**
 * (`../../修仙恋爱世界推进`), AI 只负责报告经过了多少天、去了哪里, 然后读
 * `世界._移动日志` 与 `主角._修行日志` 了解脚本做了什么.
 *
 * ## 写作约定 (遵循 .agents/skills/mvu-character-card)
 *
 * - 只用 `z` 与 `_`, 二者已全局注入, 不要 import
 * - 幂等: `Schema.parse(Schema.parse(x))` 必须等于 `Schema.parse(x)`
 * - 用 `.prefault()` 而非 `.default()`; 复合类型的每个字段都要 prefault
 * - 越界用 `z.transform` 夹取而不是 `.min()/.max()`
 * - 字典 (`z.record`) 优先于数组
 * - `$` 开头是只读派生值, `_` 开头是只读脚本字段, AI 都不该更新
 */
// #region 历法
/** 一年固定 365 日, 不设闰年 */
export const 一年日数 = 365;
/** 每月天数, 相加恰为 365 */
const 每月天数 = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
const 月名 = ['正月', '二月', '三月', '四月', '五月', '六月', '七月', '八月', '九月', '十月', '冬月', '腊月'];
const 日名 = [
    '初一', '初二', '初三', '初四', '初五', '初六', '初七', '初八', '初九', '初十',
    '十一', '十二', '十三', '十四', '十五', '十六', '十七', '十八', '十九', '二十',
    '廿一', '廿二', '廿三', '廿四', '廿五', '廿六', '廿七', '廿八', '廿九', '三十', '卅一',
];
/** 把数字写成汉字, 用于年份 (1~9999 够用了) */
function 中文数(数) {
    const 数字 = '零一二三四五六七八九';
    const 位 = ['', '十', '百', '千'];
    const 串 = String(Math.max(0, Math.floor(数)));
    let 输出 = '';
    let 攒着零 = false;
    for (let i = 0; i < 串.length; i++) {
        const 值 = Number(串[i]);
        if (值 === 0) {
            攒着零 = true;
            continue;
        }
        if (攒着零 && 输出 !== '') {
            输出 += '零';
        }
        攒着零 = false;
        输出 += 数字[值] + 位[串.length - 1 - i];
    }
    // "一十二" 应当写成 "十二"
    return 输出.replace(/^一十/, '十');
}
/** 表单日 = 正月初一 */
export function 格式化历日(历日, 时段 = '') {
    const 总日 = Math.max(0, Math.floor(历日));
    const 年 = Math.floor(总日 / 一年日数) + 1;
    let 余 = 总日 % 一年日数;
    let 月 = 0;
    while (月 < 每月天数.length - 1 && 余 >= 每月天数[月]) {
        余 -= 每月天数[月];
        月++;
    }
    return `大衍历${年 === 1 ? '元' : 中文数(年)}年 ${月名[月]}${日名[余]}${时段}`;
}
/** 把天数说成人话: 不足一年说日, 超过一年说年 */
export function 说时长(天数) {
    if (天数 < 一年日数) {
        return `${_.round(天数, 1)}日`;
    }
    const 年 = Math.floor(天数 / 一年日数);
    const 余日 = _.round(天数 - 年 * 一年日数, 1);
    return 余日 > 0 ? `${年}年${余日}日` : `${年}年`;
}
/** 把大数字说成人话: 一万以上用「万」, 免得日志里一长串数不清的零 */
export function 说数值(数值) {
    const 数 = _.round(数值, 1);
    if (Math.abs(数) < 10000) {
        return `${数}`;
    }
    return `${_.round(数 / 10000, 1)}万`;
}
