/** 好感度所对应的阶段, 供界面、双修加成与剧情参考 */
export function 好感阶段(好感度) {
    if (好感度 < 20) {
        return 好感阶段表[0];
    }
    if (好感度 < 40) {
        return 好感阶段表[1];
    }
    if (好感度 < 60) {
        return 好感阶段表[2];
    }
    if (好感度 < 80) {
        return 好感阶段表[3];
    }
    return 好感阶段表[4];
}
