AA,CACA,SAJW,CAKX,2BAAA,CACA,mBAAA,CAGA,wUACE,CAGF,uFACE,CAQF,2GACE,CAQF,2BAAA,CD7CJ,6BC+DE,2CAAA,CDrDA,eAAA,CAIF,mCACE,iBAAA,CACA,SAAA,CACA,iBAAA,CACA,eAAA,CACA,oBAAA,CACA,0BAAA,CACA,gCAAA,CAEA,qEACE,CAEF,uBAAA,CACA,cAAA,CACA,eAAA,CACA,mBAAA,CAEA,gBAAA,CACA,eAAA,CAGF,kCACE,iBAAA,CACA,aAAA,CACA,YAAA,CACA,eAAA,CACA,cAAA,CACA,gBAAA,CACA,eAAA,CACA,oBAAA,CACA,gDAAA,CAGF,kCACE,QAAA,CACA,uBAAA,CACA,cAAA,CACA,oBAAA,CACA,iBAAA,CACA,iBAAA,CACA,eAAA","sourcesContent":["\n@use '../水墨' as *;\n\n.side-panel {\n  position: relative;\n  display: flex;\n  flex-direction: column;\n  min-height: 0;\n  padding: 18px 15px 18px;\n  border: 1px solid var(--墨线);\n  background: linear-gradient(180deg, rgba(255, 253, 247, 0.84), rgba(255, 252, 244, 0.46));\n  @include 版框;\n  @include 墨晕(26px, 0.07);\n  overflow: hidden;\n}\n\n/* 匾额式的小题: 双线小框, 楷体宽字距 */\n.side-panel-title {\n  position: relative;\n  flex: none;\n  align-self: center;\n  margin: 0 0 15px;\n  padding: 3px 15px 4px;\n  border: 1px solid var(--墨线);\n  background: rgba(255, 254, 250, 0.92);\n  /* 第一道阴影压在第二道上, 于是露出 2px 处的一条细线, 凑成双线框 */\n  box-shadow:\n    inset 0 0 0 2px #fffdf8,\n    inset 0 0 0 3px rgba(34, 32, 28, 0.09);\n  font-family: var(--字体题签);\n  font-size: 14px;\n  font-weight: 400;\n  letter-spacing: 0.3em;\n  /* 字距会在右侧多出一格, 补回来才是视觉居中 */\n  text-indent: 0.3em;\n  color: var(--墨淡);\n}\n\n.side-panel-body {\n  position: relative;\n  flex: 1 1 auto;\n  min-height: 0;\n  overflow-y: auto;\n  font-size: 13px;\n  line-height: 1.85;\n  color: var(--墨淡);\n  scrollbar-width: thin;\n  scrollbar-color: rgba(34, 32, 28, 0.18) transparent;\n}\n\n.side-panel-hint {\n  margin: 0;\n  font-family: var(--字体题签);\n  font-size: 12px;\n  letter-spacing: 0.26em;\n  text-indent: 0.26em;\n  text-align: center;\n  color: var(--墨微);\n}\n","/**\n * 全屏界面共用的水墨装饰.\n *\n * 颜色和字体不放在这里, 而是定义在 App.vue 根节点上的 CSS 变量里 —— 自定义属性会随 DOM\n * 继承下去, 子组件直接 `var()` 就能用; 这里只放需要反复复用的绘制规则.\n */\n\n/**\n * 版框: 往里收一圈细线, 四角再各压一道短线.\n *\n * 用的是 `::before`, 所以组件自己的 `::after` 仍然空着可用.\n *\n * @param 边距 内框离元素边缘的距离\n * @param 角长 四角短线的长度\n * @param 线色 内框线颜色\n * @param 角色 四角短线颜色\n */\n@mixin 版框($边距: 6px, $角长: 14px, $线色: var(--墨线淡), $角色: var(--朱砂线)) {\n  &::before {\n    content: '';\n    position: absolute;\n    inset: $边距;\n    border: 1px solid $线色;\n    pointer-events: none;\n\n    /* 四角各一横一竖, 拼成角线 */\n    background-image:\n      linear-gradient($角色, $角色), linear-gradient($角色, $角色), linear-gradient($角色, $角色),\n      linear-gradient($角色, $角色), linear-gradient($角色, $角色), linear-gradient($角色, $角色),\n      linear-gradient($角色, $角色), linear-gradient($角色, $角色);\n    background-size:\n      $角长 1px,\n      1px $角长,\n      $角长 1px,\n      1px $角长,\n      $角长 1px,\n      1px $角长,\n      $角长 1px,\n      1px $角长;\n    background-position:\n      left top,\n      left top,\n      right top,\n      right top,\n      left bottom,\n      left bottom,\n      right bottom,\n      right bottom;\n    background-repeat: no-repeat;\n  }\n}\n\n/**\n * 两端淡出的双线, 用来当书眉线、版心线.\n *\n * 竖着排一深一浅两道细线, 再用遮罩把两端化开, 比生硬的 border-bottom 有笔意.\n */\n@mixin 双线($深: rgba(35, 32, 27, 0.38), $浅: rgba(35, 32, 27, 0.14)) {\n  height: 3px;\n  background: linear-gradient(180deg, $深 0 1px, transparent 1px 2px, $浅 2px 3px);\n  -webkit-mask-image: linear-gradient(90deg, transparent, #000 12%, #000 88%, transparent);\n  mask-image: linear-gradient(90deg, transparent, #000 12%, #000 88%, transparent);\n}\n\n/** 纸上的柔和墨晕, 代替现代的硬投影 */\n@mixin 墨晕($模糊: 26px, $强度: 0.07) {\n  box-shadow: 0 ($模糊 * 0.38) $模糊 rgba(74, 58, 38, $强度);\n}\n"],"sourceRoot":""}]);
