AAA,CAGF,oCACE,eAAA,CAIJ,iCACE,uBAAA,CACA,eAAA,CACA,mBAAA,CACA,gBAAA,CAGF,gEAEE,iBAAA,CACA,UAAA,CACA,cAAA,CACA,mBAAA,CACA,cAAA,CACA,WAAA,CACA,mBAAA,CAGF,gCACE,SAAA,CAIF,gCACE,UAAA,CACA,uBAAA,CACA,cAAA,CACA,oBAAA,CACA,iCAAA","sourcesContent":["\n@use '../水墨' as *;\n\n/* galgame 那种窄条对话框: 宽度铺满中间区域, 高度只够两三行 */\n.dialogue-box {\n  position: relative;\n  flex: none;\n  height: 112px;\n  margin-bottom: 13px;\n  border: 1px solid rgba(35, 32, 27, 0.22);\n  /* 笺纸: 上半泛白, 下半回暖, 像一张裁好的素笺 */\n  background:\n    radial-gradient(120% 150% at 50% 0%, rgba(255, 255, 255, 0.92), transparent 62%),\n    linear-gradient(180deg, #fffdf7, #f6efe2);\n  @include 版框(6px, 14px, rgba(35, 32, 27, 0.11), var(--朱砂线));\n  @include 墨晕(26px, 0.08);\n  cursor: pointer;\n  user-select: none;\n  overflow: hidden;\n  transition: border-color 0.18s ease;\n\n  &:hover {\n    border-color: var(--朱砂线);\n  }\n\n  /* 玩家自己的发言用朱砂角标出来, 免得翻着翻着分不清是谁在说 */\n  &.is-user {\n    border-color: rgba(156, 43, 35, 0.32);\n    @include 版框(6px, 14px, rgba(156, 43, 35, 0.22), rgba(156, 43, 35, 0.75));\n\n    &::after {\n      background: linear-gradient(180deg, transparent, rgba(156, 43, 35, 0.9), transparent);\n    }\n  }\n}\n\n/* 左边一道朱砂起笔 */\n.dialogue-box::after {\n  content: '';\n  position: absolute;\n  left: 6px;\n  top: 20px;\n  bottom: 20px;\n  width: 2px;\n  background: linear-gradient(180deg, transparent, var(--朱砂线), transparent);\n  pointer-events: none;\n}\n\n.dialogue-text {\n  position: absolute;\n  inset: 15px 20px 24px 25px;\n  overflow-y: auto;\n  font-size: 15px;\n  line-height: 1.78;\n  color: var(--墨);\n  scrollbar-width: thin;\n  scrollbar-color: rgba(35, 32, 27, 0.18) transparent;\n\n  /* 一句话不缩进; 也去掉段落自带的外边距, 免得窄框里被顶掉一行 */\n  :deep(p) {\n    margin: 0;\n    text-indent: 0;\n  }\n\n  :deep(p + p) {\n    margin-top: 0.4em;\n  }\n}\n\n.dialogue-empty {\n  font-family: var(--字体题签);\n  color: var(--墨微);\n  letter-spacing: 0.2em;\n  text-indent: 0.2em;\n}\n\n.dialogue-hint,\n.dialogue-page {\n  position: absolute;\n  bottom: 8px;\n  font-size: 11px;\n  letter-spacing: 0.1em;\n  color: var(--赭);\n  opacity: 0.72;\n  pointer-events: none;\n}\n\n.dialogue-hint {\n  left: 25px;\n}\n\n/* 页码用楷体, 像书口的鱼尾 */\n.dialogue-page {\n  right: 18px;\n  font-family: var(--字体题签);\n  font-size: 12px;\n  letter-spacing: 0.16em;\n  font-variant-numeric: tabular-nums;\n}\n","/**\n * 全屏界面共用的水墨装饰.\n *\n * 颜色和字体不放在这里, 而是定义在 App.vue 根节点上的 CSS 变量里 —— 自定义属性会随 DOM\n * 继承下去, 子组件直接 `var()` 就能用; 这里只放需要反复复用的绘制规则.\n */\n\n/**\n * 版框: 往里收一圈细线, 四角再各压一道短线.\n *\n * 用的是 `::before`, 所以组件自己的 `::after` 仍然空着可用.\n *\n * @param 边距 内框离元素边缘的距离\n * @param 角长 四角短线的长度\n * @param 线色 内框线颜色\n * @param 角色 四角短线颜色\n */\n@mixin 版框($边距: 6px, $角长: 14px, $线色: var(--墨线淡), $角色: var(--朱砂线)) {\n  &::before {\n    content: '';\n    position: absolute;\n    inset: $边距;\n    border: 1px solid $线色;\n    pointer-events: none;\n\n    /* 四角各一横一竖, 拼成角线 */\n    background-image:\n      linear-gradient($角色, $角色), linear-gradient($角色, $角色), linear-gradient($角色, $角色),\n      linear-gradient($角色, $角色), linear-gradient($角色, $角色), linear-gradient($角色, $角色),\n      linear-gradient($角色, $角色), linear-gradient($角色, $角色);\n    background-size:\n      $角长 1px,\n      1px $角长,\n      $角长 1px,\n      1px $角长,\n      $角长 1px,\n      1px $角长,\n      $角长 1px,\n      1px $角长;\n    background-position:\n      left top,\n      left top,\n      right top,\n      right top,\n      left bottom,\n      left bottom,\n      right bottom,\n      right bottom;\n    background-repeat: no-repeat;\n  }\n}\n\n/**\n * 两端淡出的双线, 用来当书眉线、版心线.\n *\n * 竖着排一深一浅两道细线, 再用遮罩把两端化开, 比生硬的 border-bottom 有笔意.\n */\n@mixin 双线($深: rgba(35, 32, 27, 0.38), $浅: rgba(35, 32, 27, 0.14)) {\n  height: 3px;\n  background: linear-gradient(180deg, $深 0 1px, transparent 1px 2px, $浅 2px 3px);\n  -webkit-mask-image: linear-gradient(90deg, transparent, #000 12%, #000 88%, transparent);\n  mask-image: linear-gradient(90deg, transparent, #000 12%, #000 88%, transparent);\n}\n\n/** 纸上的柔和墨晕, 代替现代的硬投影 */\n@mixin 墨晕($模糊: 26px, $强度: 0.07) {\n  box-shadow: 0 ($模糊 * 0.38) $模糊 rgba(74, 58, 38, $强度);\n}\n"],"sourceRoot":""}]);
